(()=>{if((location.pathname.replace(/\/$/,'')||'/')!=='/')return;const existing=document.querySelector('.home-slider');if(existing)existing.remove();const phone='212670779271',wa=(msg)=>`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`;const slides=panels.map((p,i)=>`<article class="server-slide ${i===0?'active':''}" data-index="${i}"><div class="server-slide-copy"><div class="eyebrow">${String(i+1).padStart(2,'0')} / ${panels.length} · ${p[2]}</div><h2>${p[1]}</h2><p>${p[7]}</p><div class="server-slide-meta"><span>📺 ${p[4]} live TV</span><span>🎬 ${p[5]} movies</span><span>📼 ${p[6]} series</span></div><div class="tags">${p[3].split(', ').map(x=>`<span class="tag">${x}</span>`).join('')}</div><div class="actions"><a class="btn cyan" href="/panels/${p[0]}/">View ${p[1]} credits</a><a class="btn green" href="${wa('Hello, I want a free '+p[1]+' test line (M3U/Xtream).')}" target="_blank">Free M3U / Xtream trial</a></div></div><div class="server-slide-mark">${p[1].split(/\s|\//).map(x=>x[0]).join('').slice(0,3)}</div></article>`).join('');document.querySelector('main')?.insertAdjacentHTML('beforeend',`<section class="server-carousel"><div class="wrap"><div class="eyebrow">Available server showcase</div><h2>Explore every IPTV and OTT reseller server.</h2><p class="sub">Browse panel features, catalog snapshots and target GEO coverage before opening its credit page.</p><div class="server-carousel-frame">${slides}<div class="server-carousel-bar"><button data-nav="previous" aria-label="Previous server">←</button><span id="serverSlideCount">1 / ${panels.length}</span><button data-nav="next" aria-label="Next server">→</button></div></div><div class="server-dots">${panels.map((p,i)=>`<button class="${i===0?'on':''}" data-dot="${i}" aria-label="Show ${p[1]}"></button>`).join('')}</div></div></section>`);document.head.insertAdjacentHTML('beforeend',`<style>.server-carousel{padding:76px 0;background:linear-gradient(180deg,#091626,#07111f)}.server-carousel-frame{position:relative;margin-top:28px;overflow:hidden;border:1px solid #20516d;border-radius:20px;background:radial-gradient(circle at 83% 18%,#125273,transparent 34%),#0b1b2d}.server-slide{display:none;min-height:350px;padding:44px;position:relative;align-items:center}.server-slide.active{display:flex}.server-slide-copy{max-width:710px;position:relative;z-index:1}.server-slide h2{font-size:clamp(32px,5vw,56px);margin:10px 0}.server-slide p{color:#b9cedd;max-width:650px;font-size:16px}.server-slide-meta{display:flex;gap:16px;flex-wrap:wrap;color:#d8f4ff;margin:21px 0 12px;font-size:14px}.server-slide-mark{position:absolute;right:52px;top:50%;transform:translateY(-50%);width:150px;height:150px;border-radius:38px;display:grid;place-items:center;background:linear-gradient(135deg,#1c789e,#0d2e4a);border:1px solid #42cbed;color:#9ff3ff;font-size:45px;font-weight:900;box-shadow:0 0 60px #00c8ff2e}.server-carousel-bar{position:absolute;right:22px;bottom:20px;display:flex;align-items:center;gap:10px;color:#b7d5e5;font-size:13px}.server-carousel-bar button{width:36px;height:34px;border-radius:8px;border:1px solid #3980a4;color:#e7fbff;background:#123047;cursor:pointer}.server-dots{display:flex;gap:7px;flex-wrap:wrap;margin-top:15px}.server-dots button{width:9px;height:9px;border-radius:50%;padding:0;border:0;background:#315a70;cursor:pointer}.server-dots button.on{background:#32d7ff;box-shadow:0 0 10px #32d7ff}@media(max-width:700px){.server-slide{padding:30px 22px 85px;min-height:410px}.server-slide-mark{width:70px;height:70px;right:18px;top:18px;transform:none;border-radius:18px;font-size:22px}.server-slide h2{max-width:75%;font-size:32px}.server-slide-meta{gap:8px;font-size:12px}.server-slide .actions{padding-right:0}.server-slide .btn{width:100%;font-size:12px}}</style>`);let index=0,all=[...document.querySelectorAll('.server-slide')],dots=[...document.querySelectorAll('.server-dots button')],count=document.getElementById('serverSlideCount');function show(n){index=(n+all.length)%all.length;all.forEach((s,i)=>s.classList.toggle('active',i===index));dots.forEach((d,i)=>d.classList.toggle('on',i===index));count.textContent=`${index+1} / ${all.length}`}document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>show(index+(b.dataset.nav==='next'?1:-1)));dots.forEach(d=>d.onclick=()=>show(+d.dataset.dot));})();
